        (N'tech-debt-analyst', N'Nina', N'modernisation', N'web-engineering', N'modernisation-lead', N'L1', N'Inventory technical debt and rank it by impact', N'sonnet', N'codebase-cleanup', 0, 0, 0, N'delivery-baseline', N'internal', N'L0-propose-only', N'Reads source-code. Holds no write tool and can change no state. Worst case if fully hijacked: up to 40 wasted steps and 200k tokens on one task before the budget halts it, plus findings that are false. Every finding is reviewed against evidence before it blocks anything, so a fabricated one costs review time and nothing else. No egress. No client data leaves the boundary.', 40, 200000, 0, N'2026-09-14', N'2027-03-15'),
        (N'dead-code-auditor', N'Otto', N'modernisation', N'web-engineering', N'modernisation-lead', N'L1', N'Find and remove unreachable code, unused exports and orphaned assets', N'haiku', N'codebase-cleanup', 1, 0, 0, N'delivery-baseline', N'internal', N'L1-supervised', N'Writes only inside its own workspace branch over source-code. Every change is Tier 1 and reversible with ''git checkout''. Worst case if fully hijacked: up to 50 bad file mutations on one branch, all of which merge-authority reviews before anything merges and none of which reach any environment. Cannot write its own configuration. No egress.', 60, 400000, 50, N'2026-09-14', N'2027-03-15'),
        (N'debugging-specialist', N'Pia', N'modernisation', N'web-engineering', N'modernisation-lead', N'L1', N'Reproduce, isolate and explain defects before anyone fixes them', N'sonnet', N'debugging-toolkit', 0, 0, 0, N'delivery-baseline', N'internal', N'L0-propose-only', N'Reads source-code. Holds no write tool and can change no state. Worst case if fully hijacked: up to 40 wasted steps and 200k tokens on one task before the budget halts it, plus findings that are false. Every finding is reviewed against evidence before it blocks anything, so a fabricated one costs review time and nothing else. No egress. No client data leaves the boundary.', 40, 200000, 0, N'2026-09-14', N'2027-03-15'),
        (N'monorepo-architect', N'Quinn', N'modernisation', N'web-engineering', N'modernisation-lead', N'L1', N'Monorepo tooling, task graphs and caching', N'opus', N'developer-essentials', 1, 0, 0, N'delivery-baseline', N'internal', N'L1-supervised', N'Writes only inside its own workspace branch over source-code, build-config. Every change is Tier 1 and reversible with ''git checkout''. Worst case if fully hijacked: up to 50 bad file mutations on one branch, all of which merge-authority reviews before anything merges and none of which reach any environment. Cannot write its own configuration. No egress.', 60, 400000, 50, N'2026-09-14', N'2027-03-15'),
        (N'shell-tooling-engineer', N'Rune', N'modernisation', N'web-engineering', N'modernisation-lead', N'L1', N'Developer scripts, task runners and local automation', N'haiku', N'shell-scripting', 1, 0, 0, N'delivery-baseline', N'internal', N'L1-supervised', N'Writes only inside its own workspace branch over build-config. Every change is Tier 1 and reversible with ''git checkout''. Worst case if fully hijacked: up to 50 bad file mutations on one branch, all of which merge-authority reviews before anything merges and none of which reach any environment. Cannot write its own configuration. No egress.', 60, 400000, 50, N'2026-09-14', N'2027-03-15')
    ) v (Name, Person, TeamCode, DeptCode, ReportsTo, DecisionLevel, [Role], Model, Capability, MaxTier, IsTeamLead, IsReadOnly, Cohort, Classification, AutonomyLevel, BlastRadius, BudgetSteps, BudgetTokens, BudgetMutations, RegisteredOn, ReviewDue)
), resolved AS (
    SELECT src.*, t.TeamId, d.DepartmentId
    FROM src JOIN gov.Department d ON d.Code = src.DeptCode
             JOIN gov.Team       t ON t.Code = src.TeamCode AND t.DepartmentId = d.DepartmentId
)
MERGE gov.Agent AS tgt
USING resolved AS src ON tgt.Name = src.Name
WHEN MATCHED AND EXISTS (
        SELECT src.Person, src.TeamId, src.DepartmentId, src.ReportsTo, src.DecisionLevel, src.[Role],
               src.Model, src.Capability, src.MaxTier, src.IsTeamLead, src.IsReadOnly,
               src.Cohort, src.Classification, src.AutonomyLevel, src.BlastRadius,
               src.BudgetSteps, src.BudgetTokens, src.BudgetMutations
        EXCEPT
        SELECT tgt.Person, tgt.TeamId, tgt.DepartmentId, tgt.ReportsTo, tgt.DecisionLevel, tgt.[Role],
               tgt.Model, tgt.Capability, tgt.MaxTier, tgt.IsTeamLead, tgt.IsReadOnly,
               tgt.Cohort, tgt.Classification, tgt.AutonomyLevel, tgt.BlastRadius,
               tgt.BudgetSteps, tgt.BudgetTokens, tgt.BudgetMutations
     ) THEN UPDATE SET
        tgt.Person = src.Person, tgt.TeamId = src.TeamId, tgt.DepartmentId = src.DepartmentId,
        tgt.ReportsTo = src.ReportsTo, tgt.DecisionLevel = src.DecisionLevel,
        tgt.[Role] = src.[Role], tgt.Model = src.Model, tgt.Capability = src.Capability,
        tgt.MaxTier = src.MaxTier, tgt.IsTeamLead = src.IsTeamLead,
        tgt.IsReadOnly = src.IsReadOnly, tgt.Cohort = src.Cohort,
        tgt.Classification = src.Classification, tgt.AutonomyLevel = src.AutonomyLevel,
        tgt.BlastRadius = src.BlastRadius, tgt.BudgetSteps = src.BudgetSteps,
        tgt.BudgetTokens = src.BudgetTokens, tgt.BudgetMutations = src.BudgetMutations,
        tgt.ReviewDue = src.ReviewDue
WHEN NOT MATCHED BY TARGET THEN
    INSERT (Name, Person, TeamId, DepartmentId, ReportsTo, DecisionLevel, [Role], Model, Capability,
            MaxTier, IsTeamLead, IsReadOnly, Cohort, Classification, AutonomyLevel,
            BlastRadius, BudgetSteps, BudgetTokens, BudgetMutations, RegisteredOn, ReviewDue)
    VALUES (src.Name, src.Person, src.TeamId, src.DepartmentId, src.ReportsTo, src.DecisionLevel,
            src.[Role], src.Model, src.Capability, src.MaxTier, src.IsTeamLead,
            src.IsReadOnly, src.Cohort, src.Classification, src.AutonomyLevel,
            src.BlastRadius, src.BudgetSteps, src.BudgetTokens, src.BudgetMutations,
            src.RegisteredOn, src.ReviewDue)
WHEN NOT MATCHED BY SOURCE THEN DELETE;
GO


;WITH src ([Name], [Version], [Owner], [Description], [Irreversibility], [Idempotent], [Rollback], [ResourcePattern], [Approval], [PerTaskLimit], [MutationBudget], [RetentionDays], [IsGrantable]) AS (
    SELECT * FROM (VALUES
        (N'repository.read', 1, N'platform-engineering', N'Read a file from the bound repository.', 0, 1, NULL, N'repository:{repository_id}/read-only', N'none', 400, 0, 2555, 1),
        (N'repository.search', 1, N'platform-engineering', N'Search file contents in the bound repository.', 0, 1, NULL, N'repository:{repository_id}/read-only', N'none', 400, 0, 2555, 1),
        (N'observability.read', 1, N'site-reliability', N'Read traces, metrics and the trajectory log.', 0, 1, NULL, N'observability:{tenant_id}/read-only', N'none', 200, 0, 2555, 1),
        (N'database.query', 1, N'data-and-ai', N'Run a read-only SELECT against a bound database.', 0, 1, NULL, N'database:{tenant_id}/{database_name}/read-only', N'none', 100, 0, 2555, 1),
        (N'repository.write', 1, N'platform-engineering', N'Write a file in the agent''s workspace branch.', 1, 1, N'git checkout -- <path>', N'repository:{repository_id}/workspace/{branch}', N'none', 100, 100, 2555, 1),
        (N'repository.edit', 1, N'platform-engineering', N'Replace an exact string in a workspace file.', 1, 0, N'git checkout -- <path>', N'repository:{repository_id}/workspace/{branch}', N'none', 200, 200, 2555, 1),
        (N'branch.commit', 1, N'release-engineering', N'Commit staged changes to a workspace branch.', 1, 0, N'git reset --hard <previous-sha>', N'repository:{repository_id}/workspace/{branch}', N'none', 20, 20, 2555, 1),
        (N'record.soft_delete', 1, N'data-and-ai', N'Mark a record deleted with a tombstone. Physical removal is not performed.', 1, 1, N'UPDATE <table> SET deleted_at = NULL WHERE id = <id>', N'database:{tenant_id}/{database_name}/{table}', N'none', 50, 50, 2555, 1),
        (N'finding.raise', 1, N'compliance-and-governance', N'Record a review, compliance or security finding against a project.', 1, 1, N'finding.withdraw <finding_id>', N'project:{project_id}/findings', N'none', 40, 40, 2555, 1),
        (N'database.migrate', 1, N'data-and-ai', N'Apply a schema migration that has a tested down-migration.', 2, 1, N'alembic downgrade <revision>   # MUST have been executed in test first', N'database:{tenant_id}/{database_name}/schema', N'single', 3, 3, 2555, 1),
        (N'deploy.canary', 1, N'platform-engineering', N'Deploy to a bounded canary slice with declared halt criteria.', 2, 1, N'deploy.rollback <previous-release-id>', N'environment:{environment}/canary', N'single', 5, 5, 2555, 1),
        (N'release.promote', 1, N'release-engineering', N'Promote a release between environments after every gate job succeeded.', 2, 1, N'release.rollback <previous-release-id>', N'release:{release_id}/{environment}', N'single', 2, 2, 2555, 1),
        (N'dependency.pin', 1, N'supply-chain', N'Pin or bump a dependency to an exact commit and record its certification.', 2, 1, N'dependency.pin <previous-sha>', N'repository:{repository_id}/lockfile', N'single', 10, 10, 2555, 1),
        (N'credential.revoke', 1, N'human-resources', N'Revoke credentials held by a decommissioned agent.', 2, 1, N'identity.reissue <agent_id>   # deliberate re-hire, logged', N'identity:agent/{agent_id}', N'single', 5, 5, 2555, 1),
        (N'repository.force_push', 1, N'release-engineering', N'Overwrite branch history.', 3, 0, NULL, N'repository:{repository_id}/*', N'two_person', 0, 0, 2555, 0),
        (N'infrastructure.destroy', 1, N'platform-engineering', N'Destroy infrastructure resources.', 3, 0, NULL, N'environment:{environment}/*', N'two_person', 0, 0, 2555, 0),
        (N'email.send', 1, N'service-management', N'Send an email outside the trust boundary.', 4, 1, NULL, N'messaging:{tenant_id}/outbound', N'two_person', 0, 0, 2555, 0),
        (N'repository.make_public', 1, N'platform-engineering', N'Change repository or bucket visibility to public.', 4, 1, NULL, N'repository:{repository_id}/visibility', N'two_person', 0, 0, 2555, 0),
        (N'payment.transfer', 1, N'finance', N'Move money.', 4, 1, NULL, N'payments:{tenant_id}/*', N'two_person', 0, 0, 2555, 0)
    ) v ([Name], [Version], [Owner], [Description], [Irreversibility], [Idempotent], [Rollback], [ResourcePattern], [Approval], [PerTaskLimit], [MutationBudget], [RetentionDays], [IsGrantable])
)
MERGE gov.Tool AS tgt
USING src ON tgt.[Name] = src.[Name]
WHEN MATCHED AND EXISTS (
        SELECT src.[Version], src.[Owner], src.[Description], src.[Irreversibility], src.[Idempotent], src.[Rollback], src.[ResourcePattern], src.[Approval], src.[PerTaskLimit], src.[MutationBudget], src.[RetentionDays], src.[IsGrantable] EXCEPT SELECT tgt.[Version], tgt.[Owner], tgt.[Description], tgt.[Irreversibility], tgt.[Idempotent], tgt.[Rollback], tgt.[ResourcePattern], tgt.[Approval], tgt.[PerTaskLimit], tgt.[MutationBudget], tgt.[RetentionDays], tgt.[IsGrantable]
     ) THEN UPDATE SET tgt.[Version] = src.[Version], tgt.[Owner] = src.[Owner], tgt.[Description] = src.[Description], tgt.[Irreversibility] = src.[Irreversibility], tgt.[Idempotent] = src.[Idempotent], tgt.[Rollback] = src.[Rollback], tgt.[ResourcePattern] = src.[ResourcePattern], tgt.[Approval] = src.[Approval], tgt.[PerTaskLimit] = src.[PerTaskLimit], tgt.[MutationBudget] = src.[MutationBudget], tgt.[RetentionDays] = src.[RetentionDays], tgt.[IsGrantable] = src.[IsGrantable]
WHEN NOT MATCHED BY TARGET THEN
    INSERT ([Name], [Version], [Owner], [Description], [Irreversibility], [Idempotent], [Rollback], [ResourcePattern], [Approval], [PerTaskLimit], [MutationBudget], [RetentionDays], [IsGrantable]) VALUES (src.[Name], src.[Version], src.[Owner], src.[Description], src.[Irreversibility], src.[Idempotent], src.[Rollback], src.[ResourcePattern], src.[Approval], src.[PerTaskLimit], src.[MutationBudget], src.[RetentionDays], src.[IsGrantable])
WHEN NOT MATCHED BY SOURCE THEN DELETE;
GO


INSERT INTO gov.ToolBlockedIf (ToolId, Condition)
SELECT t.ToolId, v.Condition
FROM (VALUES
    (N'repository.write', N'change_freeze.active'),
    (N'repository.write', N'target.is_agent_configuration'),
    (N'repository.edit', N'change_freeze.active'),
    (N'repository.edit', N'target.is_agent_configuration'),
    (N'branch.commit', N'change_freeze.active'),
    (N'branch.commit', N'flags.contains_no_verify'),
    (N'record.soft_delete', N'change_freeze.active'),
    (N'database.migrate', N'change_freeze.active'),
    (N'database.migrate', N'session.contains_untrusted_content'),
    (N'database.migrate', N'down_migration.untested'),
    (N'deploy.canary', N'change_freeze.active'),
    (N'deploy.canary', N'environment.is_production_without_approval'),
    (N'deploy.canary', N'halt_criteria.undeclared'),
    (N'release.promote', N'change_freeze.active'),
    (N'release.promote', N'gate.any_job_not_success'),
    (N'release.promote', N'veto.any_active'),
    (N'dependency.pin', N'change_freeze.active'),
    (N'dependency.pin', N'pin.is_branch_name'),
    (N'dependency.pin', N'certification.missing'),
    (N'repository.force_push', N'always'),
    (N'infrastructure.destroy', N'always'),
    (N'email.send', N'session.contains_untrusted_content'),
    (N'repository.make_public', N'always'),
    (N'payment.transfer', N'always')
) v (ToolName, Condition)
JOIN gov.Tool t ON t.Name = v.ToolName;
GO


INSERT INTO gov.AgentDomain (AgentId, Domain)
SELECT ag.AgentId, v.Domain
FROM (VALUES
    (N'review-board-lead', N'source-code'),
    (N'code-reviewer', N'source-code'),
