FROM (VALUES
    (N'review-board-lead', N'reviewer-independence-routing', N'Never routing a candidate to a reviewer who contributed to it'),
    (N'code-reviewer', N'defect-evidence-standard', N'Every finding carries a concrete failure scenario — inputs, state, and the wrong outcome'),
    (N'architect-reviewer', N'boundary-violation-detection', N'Finding the import that crosses a layer, and why it will be load-bearing in six months'),
    (N'error-path-reviewer', N'failure-mode-enumeration', N'Walking every branch that is not the happy path — the most common blocking finding here'),
    (N'dependency-review-engineer', N'dependency-justification-review', N'Asking what this dependency costs to maintain, not only what it saves to adopt'),
    (N'diff-scope-auditor', N'scope-drift-detection', N'Finding the unrelated change riding along in an approved diff'),
    (N'artifact-completeness-validator', N'artifact-precondition-check', N'DESIGN.md, tests, ADR and registration records present before a candidate is reviewable at all'),
    (N'accessibility-lead', N'wcag-conformance-scoping', N'Which success criteria apply to this interface, and the evidence each one needs'),
    (N'accessibility-expert', N'assistive-technology-audit', N'Auditing with a screen reader running, because the accessibility tree on paper is not the experience'),
    (N'accessibility-automation-analyst', N'automated-scan-limits', N'Naming the roughly two-thirds of WCAG no scanner can decide, so a green scan is not read as conformance'),
    (N'inclusive-content-analyst', N'plain-language-review', N'Reading level, sentence length and instructions a stressed user can follow'),
    (N'agent-governance-lead', N'readiness-gate-scoring', N'Scoring Appendix B from evidence rather than intent — a kill switch never pulled is a no'),
    (N'registration-record-auditor', N'blast-radius-verification', N'Rejecting any blast radius that is not a number and a bound'),
    (N'nonconformance-recorder', N'nonconformance-evidence-chain', N'A finding, its evidence, its owner and its expiry — an exception with no expiry is a permanent gap'),
    (N'regulatory-mapping-analyst', N'framework-currency-review', N'Re-verifying framework versions and regulatory deadlines every six months, because they move'),
    (N'database-lead', N'grain-and-retention-decisions', N'Deciding the row''s meaning and its lifespan before the first INSERT, because both are migrations later'),
    (N'database-architect', N'storage-engine-selection', N'Relational, document, time-series or vector chosen from access pattern rather than familiarity'),
    (N'sql-pro', N'set-based-query-construction', N'Replacing procedural loops with set operations, and reading a query plan before optimising'),
    (N'database-optimizer', N'index-strategy-design', N'Covering indexes, selectivity and the write cost every index quietly adds'),
    (N'database-admin', N'restore-drill-execution', N'A backup that has never been restored is not a backup — running the drill and publishing measured RTO'),
    (N'migration-engineer', N'zero-downtime-migration', N'Expand-migrate-contract, and never shipping a migration whose down path was not run'),
    (N'postgres-specialist', N'postgres-feature-selection', N'JSONB, partial indexes, CTEs and when each stops being the right tool'),
    (N'sqlserver-specialist', N'tsql-and-temporal-tables', N'System-versioned temporal tables for audit history the application cannot rewrite'),
    (N'vector-database-engineer', N'embedding-index-design', N'Chunking, dimensionality and recall measured against a labelled set'),
    (N'data-retention-engineer', N'retention-enforcement', N'Soft-delete, tombstone and a reaper identity the agents cannot assume'),
    (N'data-engineering-lead', N'data-contract-definition', N'Schema, freshness and completeness promised to consumers — and alerted on when broken'),
    (N'data-engineer', N'idempotent-pipeline-design', N'Reruns that produce the same result, because a pipeline will be rerun'),
    (N'pyspark-engineer', N'spark-shuffle-awareness', N'Partitioning and broadcast joins, and spotting the shuffle that dominates the job'),
    (N'data-quality-engineer', N'expectation-suite-design', N'Failing the batch loudly rather than letting bad rows reach a dashboard'),
