    (N'backend-architect', N'api-contract-design', N'Resource modelling, versioning and the errors a client can actually handle'),
    (N'django-pro', N'django-orm-discipline', N'select_related, prefetch_related and finding the N+1 before it reaches load test'),
    (N'django-pro', N'drf-serializer-design', N'Serializers that validate at the boundary instead of trusting the view'),
    (N'fastapi-pro', N'fastapi-async-architecture', N'Async boundaries, background tasks, and not blocking the loop with sync I/O'),
    (N'graphql-architect', N'graphql-schema-design', N'Nullability, pagination and dataloader batching that stops resolver fan-out'),
    (N'api-security-engineer', N'authorization-on-resolved-entity', N'Authorising the entity, not the endpoint — the difference OWASP ASI03 turns on'),
    (N'auth-systems-engineer', N'token-lifecycle-design', N'Short leases, rotation, and revocation that actually takes effect'),
    (N'event-sourcing-architect', N'event-store-modelling', N'Event granularity, versioning, and replays that rebuild a projection deterministically'),
    (N'background-jobs-engineer', N'idempotent-job-design', N'Idempotency keys and at-least-once delivery, because retries will happen'),
    (N'caching-engineer', N'cache-invalidation-strategy', N'Choosing TTL, tag or write-through per access pattern, and naming the staleness you accept'),
    (N'file-and-media-engineer', N'untrusted-upload-handling', N'Type sniffing, size caps and out-of-band processing for files you did not author'),
    (N'search-engineer', N'relevance-tuning', N'Analysers, ranking and measuring relevance against a labelled set rather than by feel'),
    (N'realtime-engineer', N'realtime-connection-management', N'Backpressure, reconnection and the fan-out ceiling you must declare up front'),
    (N'payment-integration', N'hosted-payment-integration', N'Hosted fields and SAQ-A scope: keeping card data out of our systems entirely'),
    (N'payment-integration', N'webhook-verification', N'Signature checks, replay windows and idempotent webhook handlers'),
    (N'languages-lead', N'language-selection-advice', N'When a second language earns its maintenance cost, and when it does not'),
    (N'python-pro', N'python-type-discipline', N'Protocols, generics and strict mypy settings that catch defects at edit time'),
    (N'python-pro', N'python-async-patterns', N'asyncio structure, cancellation and the sync-in-async trap'),
    (N'typescript-pro', N'type-level-api-design', N'Types that make the wrong call unrepresentable rather than merely flagged'),
    (N'javascript-pro', N'event-loop-reasoning', N'Microtasks, starvation and why an await in a loop is usually the bug'),
    (N'golang-pro', N'go-concurrency-patterns', N'Context propagation, cancellation and closing channels exactly once'),
    (N'rust-pro', N'ownership-and-lifetimes', N'Borrow-checker shapes that avoid fighting it, and when Arc is the honest answer'),
    (N'cpp-pro', N'raii-resource-discipline', N'Ownership types and why a raw owning pointer is a review finding'),
    (N'c-pro', N'bounds-and-lifetime-auditing', N'Every allocation paired, every buffer bounded, every free once'),
    (N'java-pro', N'jvm-concurrency-modelling', N'Virtual threads, structured concurrency and where the old pool model still wins'),
    (N'kotlin-pro', N'coroutine-scope-discipline', N'Structured concurrency, scope ownership and cancellation that propagates'),
    (N'csharp-pro', N'dotnet-async-patterns', N'ConfigureAwait, cancellation tokens and avoiding sync-over-async deadlocks'),
    (N'scala-pro', N'functional-error-modelling', N'Either, Validated and making failure a value rather than an exception'),
    (N'elixir-pro', N'otp-supervision-design', N'Let-it-crash with supervision trees that restart into a known-good state'),
    (N'haskell-pro', N'effect-typing', N'Pushing effects to the edges so the core stays total and testable'),
    (N'php-pro', N'php-modernisation-patterns', N'Strict types, DI containers and leaving the superglobal era behind'),
    (N'ruby-pro', N'rails-convention-discipline', N'Fat model, thin controller — and where that advice stops being true'),
    (N'modernisation-lead', N'strangler-fig-sequencing', N'Incremental replacement where every step is shippable and reversible'),
    (N'legacy-modernizer', N'characterisation-testing', N'Pinning current behaviour in tests before changing any of it'),
    (N'code-refactoring-engineer', N'refactor-without-rewrite', N'Behaviour-preserving moves, and recognising when duplication is cheaper than the wrong abstraction'),
    (N'tech-debt-analyst', N'debt-impact-scoring', N'Scoring debt by change frequency times defect density, not by how ugly it looks'),
    (N'dead-code-auditor', N'reachability-analysis', N'Proving a path is dead before deleting it, including dynamic and reflective callers'),
    (N'debugging-specialist', N'minimal-reproduction-construction', N'Shrinking a failure to its smallest reproducing case before proposing a cause'),
    (N'monorepo-architect', N'task-graph-design', N'Dependency graphs and remote cache keys that make CI incremental rather than total'),
    (N'shell-tooling-engineer', N'portable-script-authoring', N'Scripts that fail loudly, set -euo pipefail, and behave the same on CI and a laptop')
) v (AgentName, Code, About)
JOIN gov.Agent ag ON ag.Name = v.AgentName;
GO


