;WITH src ([Decision], [Rationale]) AS (
    SELECT * FROM (VALUES
        (N'what to build', N'Commercial priority.'),
        (N'whether the design is right', N'The anti-sameness judgement.'),
        (N'whether to override a veto', N'Three officers can stop a release; only the CEO unstops it.'),
        (N'off-stack technology', N'Changes cost structure, not just stack.')
    ) v ([Decision], [Rationale])
)
MERGE gov.ReservedDecision AS tgt
USING src ON tgt.[Decision] = src.[Decision]
WHEN MATCHED AND EXISTS (
        SELECT src.[Rationale] EXCEPT SELECT tgt.[Rationale]
     ) THEN UPDATE SET tgt.[Rationale] = src.[Rationale]
WHEN NOT MATCHED BY TARGET THEN
    INSERT ([Decision], [Rationale]) VALUES (src.[Decision], src.[Rationale])
WHEN NOT MATCHED BY SOURCE THEN DELETE;
GO


;WITH src ([Code], [Label], [Stack]) AS (
    SELECT * FROM (VALUES
        (N'A', N'Database-backed web', N'Django + React'),
        (N'B', N'Static-first web', N'Vite + React, no DB'),
        (N'C1', N'Android native', N'Kotlin + Jetpack Compose'),
        (N'C2', N'Cross-platform mobile', N'Flutter / Dart 3'),
        (N'C3', N'Mobile companion', N'React Native + Expo')
    ) v ([Code], [Label], [Stack])
)
MERGE gov.Lane AS tgt
USING src ON tgt.[Code] = src.[Code]
WHEN MATCHED AND EXISTS (
        SELECT src.[Label], src.[Stack] EXCEPT SELECT tgt.[Label], tgt.[Stack]
     ) THEN UPDATE SET tgt.[Label] = src.[Label], tgt.[Stack] = src.[Stack]
WHEN NOT MATCHED BY TARGET THEN
    INSERT ([Code], [Label], [Stack]) VALUES (src.[Code], src.[Label], src.[Stack])
WHEN NOT MATCHED BY SOURCE THEN DELETE;
GO


;WITH src ([TemplateId], [Code], [LaneCode], [IsKeystone]) AS (
    SELECT * FROM (VALUES
        (1, N'school', N'A', 0),
        (2, N'corporate', N'A', 0),
        (3, N'portfolio', N'B', 0),
        (4, N'restaurant', N'B', 0),
        (5, N'booking', N'A', 1),
        (6, N'healthcare', N'A', 0),
        (7, N'ecommerce', N'A', 0),
        (8, N'lms', N'A', 0),
        (9, N'saas-dashboard', N'A', 0),
        (10, N'crm', N'A', 0)
    ) v ([TemplateId], [Code], [LaneCode], [IsKeystone])
)
MERGE gov.Template AS tgt
USING src ON tgt.[TemplateId] = src.[TemplateId]
WHEN MATCHED AND EXISTS (
        SELECT src.[Code], src.[LaneCode], src.[IsKeystone] EXCEPT SELECT tgt.[Code], tgt.[LaneCode], tgt.[IsKeystone]
     ) THEN UPDATE SET tgt.[Code] = src.[Code], tgt.[LaneCode] = src.[LaneCode], tgt.[IsKeystone] = src.[IsKeystone]
WHEN NOT MATCHED BY TARGET THEN
    INSERT ([TemplateId], [Code], [LaneCode], [IsKeystone]) VALUES (src.[TemplateId], src.[Code], src.[LaneCode], src.[IsKeystone])
WHEN NOT MATCHED BY SOURCE THEN DELETE;
GO


;WITH src ([Code], [Scope], [OwnerOfficer]) AS (
    SELECT * FROM (VALUES
        (N'STD-AGENT-001', N'company', N'platform-architect'),
        (N'ISO/IEC 42001', N'company', N'quality-compliance'),
        (N'EU AI Act Art. 12/14/19', N'company', N'quality-compliance'),
        (N'GDPR', N'company', N'data-protection-officer'),
        (N'OWASP Top 10 for Agentic Applications 2026', N'company', N'security-engineer'),
        (N'WCAG 2.2 AA', N'company', N'design-owner'),
        (N'HIPAA', N'project', N'data-protection-officer'),
        (N'PCI-DSS', N'project', N'security-engineer'),
        (N'SOC2', N'project', N'quality-compliance')
    ) v ([Code], [Scope], [OwnerOfficer])
)
MERGE gov.ComplianceRegime AS tgt
USING src ON tgt.[Code] = src.[Code]
WHEN MATCHED AND EXISTS (
        SELECT src.[Scope], src.[OwnerOfficer] EXCEPT SELECT tgt.[Scope], tgt.[OwnerOfficer]
     ) THEN UPDATE SET tgt.[Scope] = src.[Scope], tgt.[OwnerOfficer] = src.[OwnerOfficer]
WHEN NOT MATCHED BY TARGET THEN
    INSERT ([Code], [Scope], [OwnerOfficer]) VALUES (src.[Code], src.[Scope], src.[OwnerOfficer])
WHEN NOT MATCHED BY SOURCE THEN DELETE;
GO


INSERT INTO gov.TemplateRegime (TemplateId, RegimeCode)
SELECT v.TemplateId, v.RegimeCode
FROM (VALUES
    (6, N'HIPAA'),
    (7, N'PCI-DSS'),
    (9, N'SOC2'),
    (10, N'SOC2')
) v (TemplateId, RegimeCode);
GO


;WITH src ([Model], [EffectiveFrom], [InputPerMTok], [OutputPerMTok], [Note]) AS (
    SELECT * FROM (VALUES
        (N'opus', N'2026-09-14', 5.0, 25.0, N'Reviewers, vetoes, architects'),
        (N'sonnet', N'2026-09-14', 3.0, 15.0, N'Default engineering tier'),
        (N'haiku', N'2026-09-14', 1.0, 5.0, N'High-volume, low-judgement work'),
        (N'fable', N'2026-09-14', 10.0, 50.0, N'~2.6x Opus. Opt-in only. Never for security agents'),
        (N'inherit', N'2026-09-14', NULL, NULL, N'Takes the caller''s tier')
    ) v ([Model], [EffectiveFrom], [InputPerMTok], [OutputPerMTok], [Note])
)
MERGE fin.RateCard AS tgt
USING src ON tgt.[Model] = src.[Model] AND tgt.[EffectiveFrom] = src.[EffectiveFrom]
WHEN MATCHED AND EXISTS (
        SELECT src.[InputPerMTok], src.[OutputPerMTok], src.[Note] EXCEPT SELECT tgt.[InputPerMTok], tgt.[OutputPerMTok], tgt.[Note]
     ) THEN UPDATE SET tgt.[InputPerMTok] = src.[InputPerMTok], tgt.[OutputPerMTok] = src.[OutputPerMTok], tgt.[Note] = src.[Note]
WHEN NOT MATCHED BY TARGET THEN
    INSERT ([Model], [EffectiveFrom], [InputPerMTok], [OutputPerMTok], [Note]) VALUES (src.[Model], src.[EffectiveFrom], src.[InputPerMTok], src.[OutputPerMTok], src.[Note])
WHEN NOT MATCHED BY SOURCE THEN DELETE;
GO


